/*
 * 这是一个计算两个字符串相似度的函数 (基于 Levenshtein 距离)
 * 您不需要修改这个函数
 */
function getSimilarity(a, b) {
  // 内部函数：计算 Levenshtein 距离
  function getLevenshteinDistance(a, b) {
    if (a.length === 0) return b.length;
    if (b.length === 0) return a.length;
    const matrix = [];
    for (let i = 0; i <= b.length; i++) {
      matrix[i] = [i];
    }
    for (let j = 0; j <= a.length; j++) {
      matrix[0][j] = j;
    }
    for (let i = 1; i <= b.length; i++) {
      for (let j = 1; j <= a.length; j++) {
        if (b.charAt(i - 1) === a.charAt(j - 1)) {
          matrix[i][j] = matrix[i - 1][j - 1];
        } else {
          matrix[i][j] = Math.min(
            matrix[i - 1][j - 1] + 1, // substitution
            matrix[i][j - 1] + 1,     // insertion
            matrix[i - 1][j] + 1      // deletion
          );
        }
      }
    }
    return matrix[b.length][a.length];
  }
  // --- 距离函数结束 ---

  const distance = getLevenshteinDistance(a, b);
  const maxLength = Math.max(a.length, b.length);
  if (maxLength === 0) return 1;
  return 1 - (distance / maxLength);
}


/*
 * --- n8n 去重主逻辑 (v1.0+ 语法) ---
 */

// 1. 定义相似度阈值 (0.8 = 80%)
// 您可以调整这个值 (0.0 到 1.0 之间)
const SIMILARITY_THRESHOLD = 0.75;

// "items" 变量在 n8n Code 节点中是自动可用的
// 它包含了所有输入的 items 数组
const filteredItems = []; // 存放最终不重复的新闻

// 2. 遍历所有输入的新闻
// (注意：这里直接使用 "items"，而不是 "$items")
for (const currentItem of items) {
  let isDuplicate = false;

  // 3. 确保 'title' 存在，如果不存在则设为空字符串
  // 这是为了防止 "cannot read property 'title' of undefined" 错误
  const currentTitle = (currentItem.json && currentItem.json.title) ? currentItem.json.title : '';

  // 4. 将当前新闻与 "filteredItems" 中已有的新闻逐个比较
  for (const existingItem of filteredItems) {
    const existingTitle = (existingItem.json && existingItem.json.title) ? existingItem.json.title : '';

    // 计算两条标题的相似度
    const similarity = getSimilarity(currentTitle, existingTitle);

    // 5. 如果相似度超过阈值，则标记为重复
    if (similarity >= SIMILARITY_THRESHOLD) {
      isDuplicate = true;
      // 已经是重复项，没必要再和 "filteredItems" 里的其他项比较了
      break; 
    }
  }

  // 6. 如果当前新闻不重复，则将其加入最终列表
  if (!isDuplicate) {
    filteredItems.push(currentItem);
  }
}

// 7. 返回去重后的 n8n item 列表
return filteredItems;

